pub fn solve(input: Vec<char>) -> Vec<char> {
    // Step 1: remove one trailing '\n' if present
    let mut s = input;
    if matches!(s.last(), Some('\n')) {
        s.pop();
    }

    // Whitespace definition for trimming
    fn is_ws(c: char) -> bool {
        matches!(c, ' ' | '\t' | '\n' | '\r')
    }

    // Step 2: repeatedly trim leading/trailing whitespace (equivalent to full trim)
    let mut start = 0usize;
    let mut end = s.len(); // exclusive
    while start < end && is_ws(s[start]) {
        start += 1;
    }
    while end > start && is_ws(s[end - 1]) {
        end -= 1;
    }

    // Step 3: validate password on the trimmed slice
    let trimmed = &s[start..end];

    let mut has_lower = false;
    let mut has_upper = false;
    let mut has_digit = false;

    for &ch in trimmed {
        if ('a'..='z').contains(&ch) {
            has_lower = true;
        } else if ('A'..='Z').contains(&ch) {
            has_upper = true;
        } else if ('0'..='9').contains(&ch) {
            has_digit = true;
        }
    }

    let ok = trimmed.len() >= 5 && has_lower && has_upper && has_digit;

    if ok {
        "Correct\n".chars().collect()
    } else {
        "Too weak\n".chars().collect()
    }
}